  _ = `„Giro be” gomb - Jobb markolat`,
  _ = `A giro-bemenet csak akkor lesz aktív, amikor a jobb markolatgomb meg van nyomva.`,
  _ = `„Giro be” gomb - Bal markolat`,
  _ = `A giro-bemenet csak akkor lesz aktív, amikor a bal markolatgomb meg van nyomva.`,
  _ = `„Giro be” gomb - Bal ravasz teljes elhúzás`,
  _ = `A giro-bemenet csak akkor lesz aktív, amikor a bal ravasz gombja meg van nyomva.`,
  _ = `„Giro be” gomb - Jobb ravasz teljes elhúzás`,
  _ = `A giro-bemenet csak akkor lesz aktív, amikor a jobb ravasz gombja meg van nyomva.`,
  _ = `„Giro be” gomb - Bal ravasz lágy elhúzás`,
  _ = `A giro-bemenet csak akkor lesz aktív, amikor a bal ravasz épp csak el van húzva.`,
  _ = `„Giro be” gomb - Jobb ravasz lágy elhúzás`,
