  _ = `A giro-bemenet csak akkor lesz aktív, amikor az „A” gomb meg van nyomva.`,
  _ = `„Giro be” gomb - B`,
  _ = `A giro-bemenet csak akkor lesz aktív, amikor a „B” gomb meg van nyomva.`,
  _ = `„Giro be” gomb - X`,
  _ = `A giro-bemenet csak akkor lesz aktív, amikor az „X” gomb meg van nyomva.`,
  _ = `„Giro be” gomb - Y`,
  _ = `A giro-bemenet csak akkor lesz aktív, amikor az „Y” gomb meg van nyomva.`,
  _ = `„Giro be” gomb - Kereszt`,
  _ = `A giro-bemenet csak akkor lesz aktív, amikor a Kereszt gomb meg van nyomva.`,
  _ = `„Giro be” gomb - Kör`,
